def _strip_tool_capability_blocks(text: str) -> str:
    if not isinstance(text, str):
        return text
    patterns = (
        r"===\s*CLIENT TOOL CAPABILITIES\s*===.*?===\s*END TOOL CAPABILITIES\s*===\s*\n\s*Caller requested tools[^\n]*(?:\n[ \t]{2,}[^\n]*)*",
        r"===\s*CLIENT TOOL CAPABILITIES\s*===.*?===\s*END TOOL CAPABILITIES\s*===",
        r"===\s*(?:UNIFIED|SERVER) TOOL CAPABILITIES\s*===.*?===\s*END (?:UNIFIED|SERVER) TOOL CAPABILITIES\s*===",
    )
    for pattern in patterns:
        text = re.sub(pattern, "", text, flags=re.DOTALL)
    return text.strip()

