def route_no_errors(events):
    internal_icon_failure = any('/favicon' in item['url'] for item in events['same_origin_failures'])
    console_errors = []
    for item in events['console']:
        text = item['text']
        if item['type'] != 'error':
            continue
        if "from origin 'null'" in text and 'more-private address space' in text:
            continue
        if internal_icon_failure and text == 'Failed to load resource: net::ERR_FAILED':
            continue
        console_errors.append(item)
    same_origin_failures = [item for item in events['same_origin_failures'] if '/favicon' not in item['url']]
    return not console_errors and not events['page_errors'] and not same_origin_failures and not events['same_origin_http_errors']

