def generate_scene_video(prompt: str, out_path: str | Path, cfg: Config | None = None,
                         duration_s: int = 5, image_refs: list[str] | None = None) -> str:
    cfg = cfg or load_config()
    out_path = Path(out_path)
    # 1. MiniMax (only if balance present — fails fast on 0 balance)
    r = minimax.generate_video(prompt, out_path, cfg, duration=duration_s,
                               image_refs=image_refs)
    if r.ok:
        return str(out_path)
    # 2. SDXL + Ken Burns motion — PRIMARY GPU path (reliable, real AI imagery).
    #    LTX-Video i2v crashes during loading on torch 2.11; gate it behind an
    #    env var so it can be re-enabled once torch/diffusers support it.
    if os.environ.get("LTX_VIDEO", "0") == "1":
        try:
            from modules import gpu_video as gv
            if gv.gpu_available():
                print(f"      [gpu] LTX i2v on RTX 3080: {prompt[:40]}...")
                start = None
                if image_refs:
                    from PIL import Image
                    start = Image.open(image_refs[0])
                return gv.generate_clip(prompt, out_path, duration_s=duration_s,
                                        start_image=start)
        except Exception as e:  # noqa
            print(f"      [gpu] LTX unavailable ({type(e).__name__}); trying SDXL+KenBurns...")
    try:
        from modules import gpu_video as gv
        if gv.gpu_available():
            print(f"      [gpu] SDXL+KenBurns: {prompt[:40]}...")
            return gv.make_kenburns_clip(prompt, out_path, duration_s=duration_s)
    except Exception as e:  # noqa
        print(f"      [gpu] SDXL+KenBurns failed ({type(e).__name__}); using placeholder")
    # 3. Placeholder (always works)
    return make_placeholder_clip(out_path, prompt, duration_s)

