def _retrieve_hybrid(self, query: str, k: int = 5) -> List[str]:
    """RRF fusion of the dense and sparse arms.

    Falls back to dense-only whenever the sparse arm is unavailable or returns
    nothing, so retrieval can never get WORSE than the dense baseline.
    """
    self._ensure_initialized()
    if not self.collection or self.collection.count() == 0:
        return []
    n = min(ARM_CANDIDATES, self.collection.count())

    dense_docs = self._retrieve_dense(query, k=n)
    dense_ids = list(range(len(dense_docs)))
    sparse_ids = self._retrieve_sparse_ids(query, k=n)

    if not sparse_ids:
        return dense_docs[:k]
    # Map sparse chunk indices onto the dense result ordering where possible so
    # both arms rank the SAME identifiers before fusion.
    index_of = {}
    try:
        got = self.collection.get(include=["documents"])
        for i, doc in enumerate(got.get("documents") or []):
            index_of.setdefault(doc, i)
    except Exception:
        index_of = {}
    sparse_ranks = [index_of.get(self._sparse_docs[i], i) for i in sparse_ids]

    fused = rrf_score([dense_ids, sparse_ranks])
    resolved: List[str] = []
    for doc_id, _score in fused:
        if 0 <= doc_id < len(dense_docs):
            resolved.append(dense_docs[doc_id])
    # Anything the sparse arm found that dense missed still deserves a slot.
    if len(resolved) < k:
        for i in sparse_ids:
            if i < len(self._sparse_docs) and self._sparse_docs[i] not in resolved:
                resolved.append(self._sparse_docs[i])
            if len(resolved) >= k:
                break
    return resolved[:k] if resolved else dense_docs[:k]

