def _ssh(command: str, timeout: int = 300) -> subprocess.CompletedProcess:
    """Run a remote command and return text stdout."""
    return subprocess.run(
        _ssh_base() + [command], capture_output=True, text=True, timeout=timeout
    )


def _ssh_binary(command: str, timeout: int = 600) -> subprocess.CompletedProcess:
    """Run a remote command and return raw bytes stdout (for tar streams)."""
    return subprocess.run(_ssh_base() + [command], capture_output=True, timeout=timeout)

