export async function fulfillCheckoutEvent(
  event: Record<string, unknown>,
  orderStore: Pick<OrderStore, 'getById' | 'markPaid'>,
): Promise<void> {
  if (event.type !== 'checkout.session.completed') return;
  const data = event.data as { object?: Record<string, unknown> } | undefined;
  const object = data?.object;
  if (!object) throw new Error('checkout session missing');
  const metadata = object.metadata as Record<string, unknown> | undefined;
  const orderId = metadata?.order_id;
  const sessionId = object.id;
  const paymentIntent = typeof object.payment_intent === 'string'
    ? object.payment_intent
    : (object.payment_intent as { id?: unknown } | undefined)?.id;
  if (typeof orderId !== 'string' || !orderId) throw new Error('order metadata missing');
  if (typeof sessionId !== 'string' || !sessionId) throw new Error('checkout session id missing');
  if (typeof paymentIntent !== 'string' || !paymentIntent) throw new Error('payment intent missing');
  const order = await orderStore.getById(orderId);
  if (object.payment_status !== 'paid') throw new Error('payment is not paid');
  if (object.amount_total !== order.priceCents) throw new Error('payment amount mismatch');
  if (typeof object.currency !== 'string' || object.currency.toLowerCase() !== order.currency) throw new Error('payment currency mismatch');
  if (metadata?.product_slug !== order.productSlug) throw new Error('product mismatch');
  if (metadata?.source_price_cents !== String(order.priceCents)) throw new Error('source price mismatch');
  if (order.checkoutSessionId && order.checkoutSessionId !== sessionId) throw new Error('checkout session mismatch');
  await orderStore.markPaid(orderId, paymentIntent, sessionId);
}

