async def start_pumps(self) -> None:
    if self._pump_tasks:
        return
    tasks = [
        asyncio.create_task(self._pump(self.to_agent, "agent")),
        asyncio.create_task(self._pump(self.to_phone, "phone")),
        asyncio.create_task(self._heartbeat()),
    ]
    # A pump that dies silently stops all audio, so surface any exception.
    for task in tasks:
        task.add_done_callback(self._log_task_exit)
    self._pump_tasks = tasks

def _log_task_exit(self, task: asyncio.Task) -> None:
    self._pump_tasks = [t for t in self._pump_tasks if t is not task]
    if task.cancelled():
        return
    exc = task.exception()
    if exc is not None:
        log_event(event="pump_task_died", error=type(exc).__name__, detail=str(exc)[:200])

async def _pump(self, queue: rc.BoundedAudioQueue, target: str) -> None:
    # BoundedAudioQueue is deliberately synchronous (drop-oldest audio, never
    # block the producer), so it is polled rather than awaited.
    while True:
        frame = queue.get()
        if frame is None:
            await asyncio.sleep(0.005)
            continue
        ws = self.agent_ws if target == "agent" else self.phone_ws
        if ws is None or ws.closed:
            continue
        try:
            if isinstance(frame, str):
                await ws.send_str(frame)
            else:
                await ws.send_bytes(frame)
        except Exception as exc:
            log_event(event="pump_send_failed", target=target, error=type(exc).__name__)
        else:
            if isinstance(frame, str) and "authorize" in frame:
                log_event(event="authorize_delivered_to_agent")

