import sqlite3, sys, time, calendar
db, qname, warn, stall = sys.argv[1], sys.argv[2], int(sys.argv[3]), int(sys.argv[4])
try:
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True, timeout=5)
    rows = con.execute(
        "SELECT id, status, command, created_at, updated_at FROM queue "
        "WHERE queue_name=? AND status IN ('waiting','running') ORDER BY id", (qname,)
    ).fetchall()
except sqlite3.OperationalError as e:
    # db/table may not exist yet on a fresh install — not a stall
    print(f"watchdog: queue not ready ({e})", flush=True)
    raise SystemExit(0)

def age_of(ts, now):
    """created_at/updated_at are SQLite 'YYYY-MM-DD HH:MM:SS' in UTC."""
    if ts is None:
        return 0.0
    s = str(ts)
    try:
        return max(0.0, now - calendar.timegm(time.strptime(s, "%Y-%m-%d %H:%M:%S")))
    except ValueError:
        return 0.0

now = time.time()
worst = 0.0
rc = 0
for tid, status, cmd, created, updated in rows:
    age = age_of(created if status == "waiting" else updated, now)
    worst = max(worst, age)
    if age > stall:
        print(f"STALL  task #{tid} {status} for {age:.0f}s (> {stall}s): {(cmd or '')[:90]}", flush=True)
        rc = 1
    elif age > warn:
        print(f"WARN   task #{tid} {status} for {age:.0f}s (> {warn}s): {(cmd or '')[:90]}", flush=True)

if not rows:
    print("OK     phone queue idle", flush=True)
elif rc == 0:
    print(f"OK     {len(rows)} task(s) in flight, head age {worst:.0f}s", flush=True)
raise SystemExit(rc)
