def _clean_opencode_output(raw_stdout: str) -> str:
    """Strip ANSI/TUI noise and agent scaffolding, return the assistant answer."""
    text = _strip_ansi(raw_stdout)
    lines = text.splitlines()
    # Find the model line (e.g. "> build · glm-5.2-high") and keep everything after it.
    body = lines
    for i, line in enumerate(lines):
        if line.lstrip().startswith("> "):
            body = lines[i + 1 :]
            break
    # Cut at the first boilerplate marker; the answer is what precedes it.
    kept = []
    for line in body:
        if any(line.lstrip().startswith(m) for m in _BOILERPLATE_MARKERS):
            break
        kept.append(line)
    answer = "\n".join(kept).strip()
    if answer:
        return answer
    # Fallback: drop leading blank/spinner lines.
    cleaned = []
    for line in body:
        if line.strip():
            cleaned.append(line)
    return "\n".join(cleaned).strip()

