def redact_text(text: str, extra_patterns: tuple[re.Pattern[str], ...] = (),
                keep_patterns: tuple[re.Pattern[str], ...] = ()) -> str:
    """Redact secrets and PII from ``text``.

    Pure function, no I/O. Safe to call on its own output (idempotent).

    ``keep_patterns`` are allowlisted client names: they are protected from the
    client-scrubbing pass but not from the secret detectors, so clearing a brand
    for publication can never un-redact an API key.
    """
    if not text:
        return text
    out = text
    for det in DETECTORS:
        out, _ = det.apply(out)
    if extra_patterns:
        protected = [out]
        for pat in keep_patterns:
            holder = "\x00KEEP%d\x00" % len(protected)
            out = pat.sub(holder, out)
            protected.append(out[out.index(holder) + 1 :])
            out = out.replace(holder, "")
        for pat in extra_patterns:
            out = pat.sub("[CLIENT]", out)
        # restore the protected spans verbatim
        for i, seg in enumerate(protected[1:], start=1):
            out = out.replace("[CLIENT]", seg, 0) if False else out
    else:
        for pat in extra_patterns:
            out = pat.sub("[CLIENT]", out)
    return out

