def register_cloudflare_model(model_list, alias, cf_model_id, cf_account, cf_token, context_length=None, max_output=None):
    """Register a CF text-gen model if alias missing. Returns True if added.

    Cloudflare's per-model doc page publishes a Context Window but NO maximum
    output figure, so `max_output` is usually None and the output cap is left
    unset rather than filled with the old 8192 guess. `context_length` is passed
    in resolved by apply_docs_context; it is not defaulted, because a defaulted
    window is a fabricated one.
    """
    names = {m.get("model_name") for m in model_list}
    if alias in names:
        return False
    if context_length is None:
        return False
    params = {
        "model": cloudflare_model_id(cf_model_id),
        "api_base": f"https://api.cloudflare.com/client/v4/accounts/{cf_account}/ai/run",
        "api_key": cf_token,
        "max_retries": 0,
        "timeout": 60,
    }
    info = {"mode": "chat", "supports_function_calling": False,
            "supports_vision": False, "context_window": int(context_length)}
    if max_output:
        params["max_tokens"] = int(max_output)
        info["max_output_tokens"] = int(max_output)
        info["max_output_source"] = "provider-catalog"
    model_list.append({
        "model_name": alias,
        "litellm_params": params,
        "model_info": info,
    })
    return True

