const BLOCKER_FIELDS = ['target', 'defect', 'evidence', 'proposed_fix', 'fix'];

function assignBlockerField(entry, key, value) {
  const normalized = key.toLowerCase().replace(/[_-]/g, '');
  const text = String(value || '').trim();
  if (normalized === 'target') entry.target = text;
  else if (normalized === 'defect') entry.defect = text;
  else if (normalized === 'evidence') entry.evidence = text;
  else entry.proposedFix = text;
}

/**
 * One blocker is normally a single line of `key: value` segments separated by
 * `|`, with `severity=` / `status=` leading. Fields may also wrap onto
 * following lines, so a bare continuation line is appended to the defect.
 */
function parseBlockerLines(body) {
  const blockers = [];
  let current = null;
  const flush = () => {
    if (current && (current.defect || current.proposedFix || current.evidence)) {
      current.defect = current.defect.trim();
      current.evidence = current.evidence.trim();
      current.proposedFix = current.proposedFix.trim();
      blockers.push(current);
    }
    current = null;
  };

  for (const rawLine of String(body || '').split('\n')) {
    const line = rawLine.trim();
    if (!line) continue;

    if (/^[-*\u2022]?\s*\[[AB]\d+\]/i.test(line) || /^[AB]\d+\s*[:.\-]/i.test(line)) {
      flush();
      const letter = (line.match(/[AB]/i) || ['B'])[0].toUpperCase();
      const digits = (line.match(/[AB](\d+)/i) || [])[1];
      current = {
        localId: `${letter}${digits || blockers.length + 1}`,
        severity: normalizeSeverity(fieldValue(line, ['severity'])),
        status: normalizeStatus(fieldValue(line, ['status'])),
        target: '',
        defect: '',
        evidence: '',
        proposedFix: ''
      };
      const rest = line
        .replace(/^[-*\u2022]?\s*\[[AB]\d+\]/i, '')
        .replace(/^[AB]\d+\s*[:.\-]\s*/i, '');
      for (const segment of rest.split('|')) {
        const field = segment.match(/^\s*(target|defect|evidence|proposed[_-]?fix|fix)\s*[:=]\s*([\s\S]*)$/i);
        if (field) assignBlockerField(current, field[1], field[2]);
      }
      continue;
    }

    if (!current) continue;
    const field = line.match(/^(target|defect|evidence|proposed[_-]?fix|fix)\s*[:=]\s*(.+)$/i);
    if (field) {
      assignBlockerField(current, field[1], field[2]);
      continue;
    }
    current.defect = `${current.defect} ${line}`.trim();
  }
  flush();
  return blockers;
}

