reference_fix:
async function openSession({ poolUrl, targetId, url, lease, connectTimeoutMs = 15000 }) {
  const port = parseInt(poolUrl.replace(/^https?:\/\//, '').split(':')[1], 10) || 9222;
  if (playwright) {
    let browser = null;
    try {
      browser = await Promise.race([
        playwright.chromium.connectOverCDP(poolUrl),
        new Promise((_, reject) => setTimeout(() => reject(new Error('playwright connect timeout')), connectTimeoutMs))
      ]);
    } catch (err) {
      console.error(`[PlaywrightAdapter] connect failed (${err.message}); using raw CDP`);
      browser = null;
    }
    if (browser) {
      try {
        const context = browser.contexts()[0];
        const page = targetId ? findOwnedPage(context, url) : null;
        if (page) return new PlaywrightSession(page, browser, lease, targetId);
      } catch (err) {
        console.error(`[PlaywrightAdapter] page lookup failed: ${err.message}`);
      }
      try {
        if (browser._connection && typeof browser._connection.close === 'function') {
          await browser._connection.close();
        }
      } catch (err) {
        console.error(`[PlaywrightAdapter] cleanup failed: ${err.message}`);
      }
    }
  }
  const CDP = require('chrome-remote-interface');
  const cdpClient = await CDP({ host: '<IP:12ca17b4>', port, target: targetId });
  return new CdpSession(cdpClient, lease, targetId);
}

