class PlaywrightSession {
  constructor(page, browser, lease, targetId) {
    this.page = page;
    this.browser = browser;
    this.lease = lease;
    this.targetId = targetId;
  }

  async enable() {}

  async navigate(url) {
    await this.page.goto(url, { waitUntil: 'domcontentloaded' }).catch(() => {});
  }

  async evaluate(expression) {
    try {
      return await this.page.evaluate((expr) => {
        // eslint-disable-next-line no-eval
        return eval(expr);
      }, expression);
    } catch (err) {
      return null;
    }
  }

  async realClick(selector) {
    const locator = this.page.locator(selector).first();
    await locator.waitFor({ state: 'attached', timeout: 5000 });
    await locator.click({ timeout: 5000 });
    return true;
  }

  async disconnect() {
    if (this.browser) {
      const b = this.browser;
      this.browser = null;
      // connectOverCDP: closing the Browser object must disconnect this client,
      // never shut down the shared browser. Playwright exposes _connection.
      try {
        if (b._connection && typeof b._connection.close === 'function') {
          await b._connection.close();
        } else if (b._playwright && b._playwright._connection && typeof b._playwright._connection.close === 'function') {
          await b._playwright._connection.close();
        } else {
          await b.close();
        }
      } catch (err) {
        console.error(`[PlaywrightAdapter] disconnect failed: ${err.message}`);
      }
    }
  }

  async close() {
    await this.disconnect();
    if (this.lease && this.targetId) {
      await this.lease.closeTab(this.targetId).catch(() => {});
    }
  }
}

