async def _aim_point(page, el, mouse=None):
    """Scroll the element into view and return a verified humanized aim
    point (viewport coords). Returns None when not actually clickable there
    (covered by overlay / off-viewport) so callers fall back safely."""
    try:
        await el.scroll_into_view_if_needed(timeout=3000)
        await asyncio.sleep(random.uniform(0.15, 0.35))
        bb = await el.bounding_box()
        if not bb:
            return None
        vp = page.viewport_size or {'width': 1280, 'height': 800}
        x = bb['x'] + bb['width'] * random.uniform(0.4, 0.6)
        y = bb['y'] + bb['height'] * random.uniform(0.4, 0.6)
        if not (0 <= x < vp['width'] and 0 <= y < vp['height']):
            return None
        ok = await el.evaluate(
            '''el => {
                const r = el.getBoundingClientRect();
                let e = document.elementFromPoint(r.x + r.width/2, r.y + r.height/2);
                while (e) { if (e === el) return true;
                            if (el.contains(e)) return true;
                            e = e.parentElement; }
                return false;
            }''')
        return (x, y) if ok else None
    except Exception:
        return None


async def human_fill(page, el, value, mouse=None):
    """Click into element like a person and type value. Fallback to fill()."""
    try:
        aim = await _aim_point(page, el, mouse)
        if aim is None:
            await el.fill(str(value))
            return False
        hm = mouse or HumanMouse(page)
        hk = HumanKeyboard(page, hm)
        await hm.click(aim[0], aim[1])
        await page.keyboard.press('Control+A')
        await page.keyboard.press('Backspace')
        await asyncio.sleep(random.uniform(0.05, 0.15))
        await hk.type_text(str(value)[:80])
        return True
    except Exception:
        try:
            await el.fill(str(value))
        except Exception:
            pass
        return False


async def human_click_element(page, el, mouse=None):
    """Trusted-input click on an element; False when impossible."""
    hm = mouse or HumanMouse(page)
    aim = await _aim_point(page, el, hm)
    if aim is not None:
        try:
            await hm.click(aim[0], aim[1])
            return True
        except Exception:
            pass
    try:
        await el.click(timeout=4000)
        return True
    except Exception:
        return False

