    """Split Markdown text into sections keyed by lowercase header text.

    Only H2 headers (##) start a new top-level section; H3 headers are kept
    as content inside the current H2 section so that role sub-headings remain
    under Professional Experience.
    """
    sections = {}
    current = None
    buffer = []
    for line in text.splitlines():
        m = re.match(r'^##\s+(.*)', line)
        if m:
            if current is not None:
                sections[current] = '\n'.join(buffer).strip()
            current = m.group(1).strip().lower()
