def _ws_open_tab(cdp_url, opener_target_id, url, timeout=12):
    """Open a tab by window.open() from the opener target over raw CDP WS.

    Chromium groups script popups into the OPENER's window — no window-manager
    focus involved, so this is deterministic even on Wayland. Returns the new
    target_id; raises on popup-block or transport failure.
    """
    import websockets

    async def fire():
        info = None
        for _ in range(10):
            for t in _http_json(cdp_url.rstrip("/") + "/json/list", 5):
                if t.get("id") == opener_target_id and t.get("webSocketDebuggerUrl"):
                    info = t
                    break
            if info:
                break
            time.sleep(0.15)
        if info is None:
            raise RuntimeError(f"opener {opener_target_id[:8]}… has no WS endpoint")
        async with websockets.connect(info["webSocketDebuggerUrl"],
                                      max_size=64 * 2 ** 20,
                                      open_timeout=10) as ws:
            expr = f"window.open({json.dumps(url)})"
            await ws.send(json.dumps({
                "id": 1, "method": "Runtime.evaluate",
                "params": {"expression": expr, "userGesture": True,
                           "returnByValue": True}}))
            deadline = time.time() + timeout
            while time.time() < deadline:
                raw = await asyncio.wait_for(ws.recv(), timeout=5)
                msg = json.loads(raw)
                if msg.get("id") == 1:
                    if msg.get("exceptionDetails"):
                        raise RuntimeError(
                            f"window.open blocked: "
                            f"{msg['exceptionDetails'].get('exception', {}).get('description', '?')}")
                    return True
        raise TimeoutError("window.open eval timed out")

    box = {}

    def run():
        try:
            box["r"] = asyncio.run(fire())
        except BaseException as exc:  # noqa: BLE001
            box["e"] = exc

    t = threading.Thread(target=run, daemon=True, name="ws-open-tab")
    t.start()
    t.join(timeout + 6)
    if "e" in box:
        raise box["e"]
    if "r" not in box:
        raise TimeoutError("ws_open_tab thread did not finish")
    return box["r"]

